56	    private IReadOnlyList<string>? _stateKeys;
57	    private readonly Func<string, CancellationToken, Task<IEnumerable<TextSearchResult>>> _searchAsync;
58	    private readonly ILogger<TextSearchProvider>? _logger;
59	    private readonly AITool[] _tools;
60	    private readonly List<ChatRole> _recentMessageRolesIncluded;
61	    private readonly int _recentMessageMemoryLimit;
62	    private readonly TextSearchProviderOptions.TextSearchBehavior _searchTime;
63	    private readonly string _contextPrompt;
64	    private readonly string _citationsPrompt;
