using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.AI;

namespace Microsoft.Agents.AI;

/// <summary>
/// An <see cref="AIContextProvider"/> that gives agents the ability to maintain a persistent todo list within a session.
/// </summary>
/// <remarks>
/// <para>
/// The provider exposes five function tools to the agent — <c>AddTodos</c>, <c>CompleteTodos</c>, <c>RemoveTodos</c>,
/// <c>GetRemainingTodos</c>, and <c>GetAllTodos</c> — which allow the agent to plan and track the steps required to
/// complete a complex, multi-step task.
/// </para>
/// <para>
/// State is persisted in the <see cref="AgentSession.StateBag"/> under the key <c>"TodoProvider"</c>, so todo items
/// added during one invocation remain available to tools obtained during subsequent invocations on the same session.
/// </para>
/// </remarks>
public sealed class TodoProvider : AIContextProvider
{
    /// <summary>
    /// The key used to store the <see cref="TodoState"/> in the <see cref="AgentSession.StateBag"/>.
    /// </summary>
    private const string TodoStateKey = "TodoProvider";

    private const string ProviderInstructions =
        "You have access to a persistent todo list to help you plan and track progress on complex, multi-step tasks. " +
        "Use the AddTodos tool to record the steps you intend to take, CompleteTodos to mark steps as done once finished, " +
        "RemoveTodos to discard steps that are no longer needed, GetRemainingTodos to review outstanding work, " +
        "and GetAllTodos to review the full list including completed items.";

    private readonly ProviderSessionState<TodoState> _sessionState;

    /// <summary>
    /// Initializes a new instance of the <see cref="TodoProvider"/> class.
    /// </summary>
    public TodoProvider()
    {
        this._sessionState = new ProviderSessionState<TodoState>(
            _ => new TodoState(),
            TodoStateKey,
            AgentJsonUtilities.DefaultOptions);
    }

    /// <inheritdoc />
    protected override ValueTask<AIContext> ProvideAIContextAsync(InvokingContext context, CancellationToken cancellationToken = default)
    {
        var session = context.Session;

        var context2 = new AIContext
        {
            Instructions = ProviderInstructions,
            Tools = this.CreateTools(session)
        };

        return new ValueTask<AIContext>(context2);
    }

    /// <summary>
    /// Gets all todo items associated with the specified session, regardless of completion status.
    /// </summary>
    /// <param name="session">The session whose todo items should be retrieved.</param>
    /// <returns>A read-only list of all todo items; an empty list for a session with no prior state.</returns>
    public IReadOnlyList<TodoItem> GetAllTodos(AgentSession? session)
        => this.GetState(session).Items;

    /// <summary>
    /// Gets the todo items associated with the specified session that have not yet been completed.
    /// </summary>
    /// <param name="session">The session whose remaining todo items should be retrieved.</param>
    /// <returns>A list of todo items where <see cref="TodoItem.IsComplete"/> is <see langword="false"/>.</returns>
    public List<TodoItem> GetRemainingTodos(AgentSession? session)
        => this.GetState(session).Items.Where(i => !i.IsComplete).ToList();

    private TodoState GetState(AgentSession? session)
        => this._sessionState.GetOrInitializeState(session);

    private AITool[] CreateTools(AgentSession? session) =>
    [
        AIFunctionFactory.Create(
            (List<TodoItemInput> todos) => this.AddTodos(session, todos),
            new AIFunctionFactoryOptions
            {
                Name = "AddTodos",
                Description = "Adds one or more items to the todo list. Each item is assigned an auto-incrementing integer id.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
        AIFunctionFactory.Create(
            (List<int> ids) => this.CompleteTodos(session, ids),
            new AIFunctionFactoryOptions
            {
                Name = "CompleteTodos",
                Description = "Marks the todo items with the specified ids as complete. Returns the number of items that were found and marked complete.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
        AIFunctionFactory.Create(
            (List<int> ids) => this.RemoveTodos(session, ids),
            new AIFunctionFactoryOptions
            {
                Name = "RemoveTodos",
                Description = "Removes the todo items with the specified ids. Returns the number of items that were removed.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
        AIFunctionFactory.Create(
            () => this.GetRemainingTodos(session),
            new AIFunctionFactoryOptions
            {
                Name = "GetRemainingTodos",
                Description = "Returns the todo items that have not yet been completed.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
        AIFunctionFactory.Create(
            () => this.GetAllTodosList(session),
            new AIFunctionFactoryOptions
            {
                Name = "GetAllTodos",
                Description = "Returns all todo items, including completed ones.",
                SerializerOptions = AgentJsonUtilities.DefaultOptions,
            }),
    ];

    private List<TodoItem> GetAllTodosList(AgentSession? session)
        => this.GetState(session).Items;

    private void AddTodos(AgentSession? session, List<TodoItemInput> todos)
    {
        var state = this.GetState(session);

        foreach (var input in todos ?? [])
        {
            state.Items.Add(new TodoItem
            {
                Id = state.NextId++,
                Title = input.Title,
                Description = input.Description,
                IsComplete = false,
            });
        }

        this._sessionState.SaveState(session, state);
    }

    private int CompleteTodos(AgentSession? session, List<int> ids)
    {
        var state = this.GetState(session);

        var idSet = new HashSet<int>(ids ?? []);
        int count = 0;
        foreach (var item in state.Items)
        {
            if (idSet.Contains(item.Id))
            {
                item.IsComplete = true;
                count++;
            }
        }

        this._sessionState.SaveState(session, state);
        return count;
    }

    private int RemoveTodos(AgentSession? session, List<int> ids)
    {
        var state = this.GetState(session);

        var idSet = new HashSet<int>(ids ?? []);
        int removed = state.Items.RemoveAll(item => idSet.Contains(item.Id));

        this._sessionState.SaveState(session, state);
        return removed;
    }
}
